import java.sql.*;import java.util.*;
public class BusPassJdbcBenchmark{
 static String url=System.getenv().getOrDefault("DB_URL","jdbc:mysql://localhost:3306/assignment5");
 static String user=System.getenv().getOrDefault("DB_USER","root"),pwd=System.getenv().getOrDefault("DB_PASSWORD","");
 static List<String[]> data(int n){List<String[]> a=new ArrayList<>(n);for(int i=0;i<n;i++)a.add(new String[]{"P"+i,"REG"+i,"Student"+i,"12","Central","2027-12-31","4500.00"});return a;}
 static void clear(Connection c)throws SQLException{try(Statement s=c.createStatement()){s.executeUpdate("DELETE FROM bus_pass");}}
 static void statement(Connection c,List<String[]> rows)throws SQLException{try(Statement s=c.createStatement()){for(String[]p:rows)s.executeUpdate("INSERT INTO bus_pass(pass_id,reg_no,name,route_no,boarding_stop,valid_until,amount) VALUES('"+p[0]+"','"+p[1]+"','"+p[2]+"',"+p[3]+",'"+p[4]+"','"+p[5]+"',"+p[6]+")");}}
 static void prepared(Connection c,List<String[]> rows)throws SQLException{String q="INSERT INTO bus_pass(pass_id,reg_no,name,route_no,boarding_stop,valid_until,amount) VALUES(?,?,?,?,?,?,?)";try(PreparedStatement p=c.prepareStatement(q)){for(String[]x:rows){bind(p,x);p.executeUpdate();}}}
 static void batch(Connection c,List<String[]> rows)throws SQLException{String q="INSERT INTO bus_pass(pass_id,reg_no,name,route_no,boarding_stop,valid_until,amount) VALUES(?,?,?,?,?,?,?)";boolean old=c.getAutoCommit();c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement(q)){int i=0;for(String[]x:rows){bind(p,x);p.addBatch();if(++i%1000==0)p.executeBatch();}p.executeBatch();c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(old);}}
 static void bind(PreparedStatement p,String[]x)throws SQLException{p.setString(1,x[0]);p.setString(2,x[1]);p.setString(3,x[2]);p.setInt(4,Integer.parseInt(x[3]));p.setString(5,x[4]);p.setDate(6,java.sql.Date.valueOf(x[5]));p.setDouble(7,Double.parseDouble(x[6]));}
 static void verify(Connection c)throws SQLException{try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM bus_pass LIMIT 1")){ResultSetMetaData m=r.getMetaData();for(int i=1;i<=m.getColumnCount();i++)System.out.println(m.getColumnName(i)+" : "+m.getColumnTypeName(i));}}
 public static void main(String[]a)throws Exception{try(Connection c=DriverManager.getConnection(url,user,pwd)){verify(c);for(int n:new int[]{10,1000,10000,100000}){List<String[]> rows=data(n);for(String mode:new String[]{"Statement","PreparedStatement","Batch"}){clear(c);long t=System.nanoTime();if(mode.equals("Statement"))statement(c,rows);else if(mode.equals("PreparedStatement"))prepared(c,rows);else batch(c,rows);System.out.printf("n=%d mode=%s elapsed_ms=%.2f%n",n,mode,(System.nanoTime()-t)/1e6);}}}}
}
